          const panelId = String(op.panel_id || "").trim();
          if (!panelId) return;
          const selector = "[data-mei-panel-id='" + cssEscape(panelId) + "']";
          const nodes = Array.from(document.querySelectorAll(selector));
          if (!nodes.length) return;
